const size_t max_relocs = 16;
    size_t bucket = argbucket;
    const void *key = argkey;
    const void *data = argdata;

    for (size_t i = 0; i < max_relocs; i++) {
        if (ckh_try_bucket_insert(ckh, bucket, key, data)) {
            return false;
        }

        /*
         * Evict a random cell from the bucket.
         */
        size_t cell_idx = ckh_prng(&ckh->prng_state) % (1U << LG_CKH_BUCKET_CELLS);
        size_t tab_idx = (bucket << LG_CKH_BUCKET_CELLS) + cell_idx;
        ckhc_t evicted_cell = ckh->tab[tab_idx];

        /*
         * Place the current item in the evicted cell's spot.
         */
        ckh->tab[tab_idx].key = key;
        ckh->tab[tab_idx].data = data;

        /*
         * Now try to relocate the evicted item.
         */
        key = evicted_cell.key;
        data = evicted_cell.data;

        size_t r_hash[2];
        ckh->hash(key, r_hash);

        /*
         * The evicted item must be moved to its other possible bucket.
         * The current bucket was either r_hash[0] or r_hash[1].
         */
        size_t b0 = r_hash[0] & ((1U << ckh->lg_curbuckets) - 1);
        size_t b1 = r_hash[1] & ((1U << ckh->lg_curbuckets) - 1);
        bucket = (bucket == b0) ? b1 : b0;
    }

    return true;

